# AUTO-GENERATED by _add_social_link_and_gating.py
"""
완성 리포트 엔드포인트.

파이프라인:
  calculate_saju()          → 사주 계산 (억부 간이판 기준)
  build_semantic_profile()  → 언어 중립 태그
  generate_full_report()    → 자연어 리포트 (en/ko)
  apply_entitlement_gate()  → 티어별 섹션 게이팅

인증:
  - 헤더 없음 → tier="free" (Step 4-A: 게이팅 적용. 이전엔 preview=ungated)
  - 인증됨   → user.tier ("free" 면 게이팅)
  - SAJU_REQUIRE_AUTH_FOR_REPORT=true 면 헤더 없을 때 401
"""
import os
import hashlib
import logging
from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from fastapi import APIRouter, Depends, HTTPException

from app.engine.calculator import calculate_saju
from app.semantic.tagger import build_semantic_profile
from app.services.content_writer import generate_full_report
from app.services.entitlements import apply_entitlement_gate
from app.auth.dependencies import get_current_user_optional
from app.schemas.saju import ReportRequest, ReportResponse
from app.api.errors import format_dst_error
from app.engine.time_correction import DSTAmbiguousError, DSTGapError

logger = logging.getLogger(__name__)
router = APIRouter()


def _resolve_today(tz_str: str):
    try:
        tz = ZoneInfo(tz_str)
    except (ZoneInfoNotFoundError, ValueError):
        tz = ZoneInfo("Asia/Seoul")
    return datetime.now(tz).date()


def _unlock_key(payload, year: int) -> str:
    """
    1회권 열람 기록 키: 같은 사람(생년월일시+성별) + 같은 연도(양력).
    언어/계산 옵션을 바꿔도 다시 결제하지 않도록 키에는 넣지 않는다.
    """
    parts = [
        str(getattr(payload, "birth_date", "")),
        str(getattr(payload, "birth_time", "") or ""),
        str(getattr(payload, "birth_time_mode", "") or ""),
        str(getattr(payload, "gender", "") or ""),
        str(year),
    ]
    digest = hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()[:40]
    return f"{year}:{digest}"  # 연도를 앞에 둬서 설정 화면에서 "올해 열림" 을 표시할 수 있게 한다


def _require_auth() -> bool:
    v = os.environ.get("SAJU_REQUIRE_AUTH_FOR_REPORT", "").lower()
    return v in ("1", "true", "yes", "on")


@router.post("/report", response_model=ReportResponse)
def api_generate_report(
    payload: ReportRequest,
    current_user: dict | None = Depends(get_current_user_optional),
):
    """
    생년월일시로 완성된 사주 리포트를 생성합니다.
    """
    if _require_auth() and current_user is None:
        raise HTTPException(
            status_code=401,
            detail=(
                "Authentication required. "
                "Create a session at /api/v1/auth/anonymous."
            ),
        )

    try:
        saju_result = calculate_saju(
            birth_date=payload.birth_date,
            birth_time=payload.birth_time,
            birth_time_mode=payload.birth_time_mode,
            timezone_str=payload.timezone_str,
            longitude=payload.longitude,
            correction_mode=payload.correction_mode,
            jasi_boundary=payload.jasi_boundary,
            gender=payload.gender,
            lang=payload.lang,
            target_year=payload.target_year,
            use_current_solar_year=payload.use_current_solar_year,
            dst_fold=payload.dst_fold,
            birth_location=payload.birth_location,
        )
    except (DSTAmbiguousError, DSTGapError) as e:
        raise HTTPException(status_code=400, detail=format_dst_error(payload.lang, e))
    except (ValueError, TypeError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        logger.exception("calculate_saju failed inside /report")
        raise HTTPException(status_code=500, detail="Calculation error.")

    try:
        profile = build_semantic_profile(saju_result)
        uid = current_user.get('id') if current_user else None
        today = _resolve_today(payload.timezone_str)
        report = generate_full_report(profile, lang=payload.lang, user_id=uid, today=today)
    except Exception:
        logger.exception("Report generation failed")
        raise HTTPException(
            status_code=500,
            detail="Report generation failed. Please try again or contact support.",
        )

    tier = "free" if current_user is None else (current_user.get("tier") or "free")
    uid = current_user.get("id") if current_user else None
    
    from app.auth.repository import get_repository
    repo = get_repository()
    
    # 💡 1회권(크레딧) 결제 유저 처리
    #    같은 사람 + 같은 해(양력) 리포트는 한 번 열면 다시 열어도 크레딧을 차감하지 않는다.
    credit_used = False
    already_unlocked = False
    onetime_credits_after = None
    if uid and tier == "free":
        unlock_year = getattr(payload, "target_year", None) or today.year
        status = repo.unlock_report_with_credit(uid, _unlock_key(payload, unlock_year))
        if status == "credit":
            tier = "premium"
            credit_used = True
            logger.info("User %s used 1 onetime credit (year=%s).", uid, unlock_year)
        elif status == "already":
            tier = "premium"
            already_unlocked = True
        onetime_credits_after = repo.get_onetime_credits(uid)

    # 1회권은 크레딧 모델로 단일화되었다(애드온 기반 심화 리포트 해제 경로 제거).
    # 애드온 테이블/조회는 남겨둔다 — 과거 행이 있어도 무시되며(참고: compatibility
    # 애드온은 궁합 엔드포인트에서 별도 판정), 여기서는 게이트에 넘기지 않는다.
    report = apply_entitlement_gate(report, tier)

    # 💡 클라이언트가 "이 리포트를 1회권으로 열었는지" 알 수 있게 meta에 표시.
    #    (홈 화면이 잔액 갱신만 하고 리포트를 다시 요청하지 않도록 → 크레딧 중복 차감 방지)
    meta = report.setdefault("meta", {})
    meta["credit_used"] = credit_used
    meta["already_unlocked"] = already_unlocked
    if onetime_credits_after is not None:
        meta["onetime_credits"] = onetime_credits_after

    return {"report": report}
